//! Parity tests for the `pi_js::vendor::jsdiff` diff functions and change converters.
//!
//! `VECTORS` / `CONVERT_VECTORS` were generated by running the real `diff@8.0.4` (libesm) under
//! Node 24 on hand-written and seeded-random inputs; each case records the JS result.

use std::sync::Arc;

use indexmap::IndexMap;
use pi_js::vendor::jsdiff::{
    AbortableDiffOptions, ArrayChange, Change, ChangeObject, DiffArraysOptions, DiffCharsOptions, DiffCssOptions,
    DiffLinesOptions, DiffSentencesOptions, DiffWordsOptions, WordSegmenter, convert_changes_to_dmp,
    convert_changes_to_xml, diff_arrays, diff_arrays_abortable, diff_chars, diff_chars_abortable, diff_css,
    diff_css_abortable, diff_lines, diff_lines_abortable, diff_sentences, diff_sentences_abortable, diff_trimmed_lines,
    diff_trimmed_lines_abortable, diff_words, diff_words_abortable, diff_words_with_space,
    diff_words_with_space_abortable,
};
use serde_json::Value;

fn num(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().expect("number"),
        Value::String(s) => match s.as_str() {
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            "NaN" => f64::NAN,
            other => panic!("bad number {other}"),
        },
        other => panic!("bad number {other}"),
    }
}

fn opt_num(o: &Value, key: &str) -> Option<f64> {
    o.get(key).filter(|v| !v.is_null()).map(num)
}

fn opt_bool(o: &Value, key: &str) -> Option<bool> {
    o.get(key).and_then(Value::as_bool)
}

fn segmenter(case: &Value) -> Option<WordSegmenter> {
    let calls = case.get("segments")?.as_object()?;
    let table: IndexMap<String, Vec<String>> = calls
        .iter()
        .map(|(k, v)| {
            let segs = v
                .as_array()
                .expect("segments")
                .iter()
                .map(|s| s.as_str().expect("segment").to_string());
            (k.clone(), segs.collect())
        })
        .collect();
    Some(Arc::new(move |s: &str| match table.get(s) {
        Some(segs) => segs.clone(),
        None => panic!("segmenter called with unrecorded input {s:?}"),
    }))
}

fn changes_value<V: serde::Serialize>(changes: Option<Vec<ChangeObject<V>>>) -> Value {
    match changes {
        Some(changes) => serde_json::to_value(changes).expect("serialize"),
        None => Value::Null,
    }
}

fn run_diff(case: &Value) -> Value {
    let f = case["f"].as_str().expect("f");
    let o = &case["o"];
    let abortable = case.get("abortable").map(|a| AbortableDiffOptions {
        max_edit_length: opt_num(a, "maxEditLength"),
        timeout: opt_num(a, "timeout"),
    });
    if f == "diffArrays" {
        let arr = |v: &Value| -> Vec<String> {
            v.as_array()
                .expect("array")
                .iter()
                .map(|s| s.as_str().expect("string").to_string())
                .collect()
        };
        let (a, b) = (arr(&case["a"]), arr(&case["b"]));
        let options = DiffArraysOptions::<String> {
            one_change_per_token: opt_bool(o, "oneChangePerToken"),
            comparator: match o.get("comparator").and_then(Value::as_str) {
                Some("ci") => Some(Arc::new(|l: &String, r: &String| l.to_lowercase() == r.to_lowercase())),
                Some(other) => panic!("unknown comparator {other}"),
                None => None,
            },
        };
        let result: Option<Vec<ArrayChange<String>>> = match abortable {
            Some(ab) => diff_arrays_abortable(&a, &b, Some(options), ab),
            None => Some(diff_arrays(&a, &b, Some(options))),
        };
        return changes_value(result);
    }
    let a = case["a"].as_str().expect("a");
    let b = case["b"].as_str().expect("b");
    let chars = || DiffCharsOptions {
        one_change_per_token: opt_bool(o, "oneChangePerToken"),
        ignore_case: opt_bool(o, "ignoreCase"),
    };
    let words = || DiffWordsOptions {
        one_change_per_token: opt_bool(o, "oneChangePerToken"),
        ignore_case: opt_bool(o, "ignoreCase"),
        intl_segmenter: segmenter(case),
        ignore_whitespace: opt_bool(o, "ignoreWhitespace"),
    };
    let lines = || DiffLinesOptions {
        one_change_per_token: opt_bool(o, "oneChangePerToken"),
        strip_trailing_cr: opt_bool(o, "stripTrailingCr"),
        newline_is_token: opt_bool(o, "newlineIsToken"),
        ignore_newline_at_eof: opt_bool(o, "ignoreNewlineAtEof"),
        ignore_whitespace: opt_bool(o, "ignoreWhitespace"),
    };
    let sentences = || DiffSentencesOptions {
        one_change_per_token: opt_bool(o, "oneChangePerToken"),
    };
    let css = || DiffCssOptions {
        one_change_per_token: opt_bool(o, "oneChangePerToken"),
    };
    let result: Option<Vec<Change>> = match (f, abortable) {
        ("diffChars", None) => Some(diff_chars(a, b, Some(chars()))),
        ("diffChars", Some(ab)) => diff_chars_abortable(a, b, Some(chars()), ab),
        ("diffWords", None) => Some(diff_words(a, b, Some(words()))),
        ("diffWords", Some(ab)) => diff_words_abortable(a, b, Some(words()), ab),
        ("diffWordsWithSpace", None) => Some(diff_words_with_space(a, b, Some(words()))),
        ("diffWordsWithSpace", Some(ab)) => diff_words_with_space_abortable(a, b, Some(words()), ab),
        ("diffLines", None) => Some(diff_lines(a, b, Some(lines()))),
        ("diffLines", Some(ab)) => diff_lines_abortable(a, b, Some(lines()), ab),
        ("diffTrimmedLines", None) => Some(diff_trimmed_lines(a, b, Some(lines()))),
        ("diffTrimmedLines", Some(ab)) => diff_trimmed_lines_abortable(a, b, Some(lines()), ab),
        ("diffSentences", None) => Some(diff_sentences(a, b, Some(sentences()))),
        ("diffSentences", Some(ab)) => diff_sentences_abortable(a, b, Some(sentences()), ab),
        ("diffCss", None) => Some(diff_css(a, b, Some(css()))),
        ("diffCss", Some(ab)) => diff_css_abortable(a, b, Some(css()), ab),
        (other, _) => panic!("unknown diff function {other}"),
    };
    changes_value(result)
}

#[test]
fn diff_functions_match_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(VECTORS).expect("vectors");
    let mut failures = Vec::new();
    for (i, case) in cases.iter().enumerate() {
        assert!(case.get("err").is_none(), "case {i} expects a JS exception: {case}");
        let actual = run_diff(case);
        if actual != case["r"] {
            failures.push(format!("case {i}: {case}\n  rust: {actual}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

#[test]
fn diff_defaults_match_options_none() {
    // `None` options behave like `{}`.
    assert_eq!(
        diff_lines("a\nb\n", "a\nc\n", None),
        diff_lines("a\nb\n", "a\nc\n", Some(DiffLinesOptions::default()))
    );
    assert_eq!(diff_words("a b", "a c", None).len(), 3);
    let trimmed = diff_trimmed_lines("a \n", "a\n", None);
    assert_eq!(trimmed.len(), 1);
    assert!(!trimmed[0].added && !trimmed[0].removed);
    assert_eq!(trimmed[0].value, "a\n");
}

fn change_from_value(v: &Value) -> Change {
    ChangeObject {
        count: v["count"].as_u64().expect("count") as usize,
        added: v["added"].as_bool().expect("added"),
        removed: v["removed"].as_bool().expect("removed"),
        value: v["value"].as_str().expect("value").to_string(),
    }
}

#[test]
fn convert_functions_match_jsdiff() {
    let cases: Vec<Value> = serde_json::from_str(CONVERT_VECTORS).expect("vectors");
    for (i, case) in cases.iter().enumerate() {
        let changes: Vec<Change> = case["changes"]
            .as_array()
            .expect("changes")
            .iter()
            .map(change_from_value)
            .collect();
        let dmp = serde_json::to_value(convert_changes_to_dmp(&changes)).expect("serialize");
        assert_eq!(dmp, case["dmp"], "case {i} dmp");
        assert_eq!(
            convert_changes_to_xml(&changes),
            case["xml"].as_str().expect("xml"),
            "case {i} xml"
        );
    }
}

